package com.bank.fdservice;
import org.springframework.dao.DuplicateKeyException;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.math.BigDecimal;import java.math.RoundingMode;import java.util.*;
@Service public class SavingsWithdrawalService {
 private final JdbcTemplate jdbc;private final PostingService postings;private final MpinProofVerifier mpin;
 public SavingsWithdrawalService(JdbcTemplate j,PostingService p,MpinProofVerifier m){jdbc=j;postings=p;mpin=m;}
 public WithdrawalResponse replayIfPresent(long actor,String key,String hash,long account){Map<String,Object> r=jdbc.query("SELECT foi_request_hash,foi_status,foi_response_reference FROM fd_operation_idempotency WHERE foi_operation_scope='CUSTOMER_SAVINGS_WITHDRAWAL' AND foi_actor_key=? AND foi_idempotency_key=?",rs->rs.next()?Map.of("hash",rs.getString(1),"status",rs.getString(2),"ref",Objects.toString(rs.getString(3),"")):null,Long.toString(actor),key);return r==null?null:replay(r,hash,account);}
 @Transactional public WithdrawalResponse withdraw(long actor,String username,String key,String hash,SavingsWithdrawalController.WithdrawalRequest req,String jti){
  try{jdbc.update("INSERT INTO fd_operation_idempotency(foi_operation_scope,foi_actor_key,foi_idempotency_key,foi_request_hash,foi_status) VALUES('CUSTOMER_SAVINGS_WITHDRAWAL',?,?,?,'PENDING')",Long.toString(actor),key,hash);}catch(DuplicateKeyException e){return replayIfPresent(actor,key,hash,req.fromAccountId());}
  mpin.consume(jti,actor,"WITHDRAWAL"); Map<String,Object> a=jdbc.query("SELECT sa_currency_id,sa_status FROM savings_accounts WHERE sa_account_id=? AND sa_holder_id=?",rs->rs.next()?Map.of("currency",rs.getLong(1),"status",rs.getString(2)):null,req.fromAccountId(),actor);if(a==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Savings account not found");if(!"ACTIVE".equals(a.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Savings account is not active");int scale=jdbc.queryForObject("SELECT fcr_decimal_places FROM fd_currency_ref WHERE fcr_currency_id=?",Integer.class,a.get("currency"));BigDecimal amount;try{amount=req.amount().setScale(scale,RoundingMode.UNNECESSARY);}catch(ArithmeticException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Amount exceeds the currency decimal scale");}if(amount.signum()<=0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Amount must be positive");String ref="WDL-"+UUID.randomUUID();PostingService.MovementResult m=postings.postSavingsMovement(req.fromAccountId(),((Number)a.get("currency")).longValue(),amount,"DEBIT",ref,req.remark()==null||req.remark().isBlank()?"Withdrawal":req.remark().trim(),username,"WITHDRAWAL:"+ref,"WITHDRAWAL","SAVINGS","WITHDRAWAL_CLEARING");jdbc.update("UPDATE fd_operation_idempotency SET foi_status='COMPLETED',foi_aggregate_id=?,foi_response_reference=?,foi_completed_at=UTC_TIMESTAMP(6) WHERE foi_operation_scope='CUSTOMER_SAVINGS_WITHDRAWAL' AND foi_actor_key=? AND foi_idempotency_key=?",req.fromAccountId(),ref,Long.toString(actor),key);return response(ref,req.fromAccountId());
 }
 private WithdrawalResponse replay(Map<String,Object> r,String hash,long account){if(!hash.equals(r.get("hash")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Idempotency key was already used for a different withdrawal");if(!"COMPLETED".equals(r.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Withdrawal is already in progress");return response(r.get("ref").toString(),account);}
 private WithdrawalResponse response(String ref,long account){Map<String,Object> r=jdbc.query("SELECT st_amount,st_currency_id,st_balance_after,st_posted_at FROM savings_transactions WHERE st_reference_id=? AND st_account_id=? AND st_entry_type='DEBIT'",rs->rs.next()?Map.of("amount",rs.getBigDecimal(1),"currency",rs.getLong(2),"balance",rs.getBigDecimal(3),"at",rs.getTimestamp(4).toInstant().toString()):null,ref,account);if(r==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Completed withdrawal history is unavailable");return new WithdrawalResponse(ref,account,(BigDecimal)r.get("amount"),jdbc.queryForObject("SELECT fcr_iso_code FROM fd_currency_ref WHERE fcr_currency_id=?",String.class,r.get("currency")),(BigDecimal)r.get("balance"),r.get("at").toString());}
 public record WithdrawalResponse(String reference,long fromAccountId,BigDecimal amount,String currency,BigDecimal balanceAfter,String postedAt){}
}
